
const WORDS=[{"id": 0, "w": "和蔼", "p": "hé'ǎi", "t": "形容词", "m": "hòa nhã, ôn hòa", "coll": "态度和蔼、和蔼可亲", "s": "那位老师态度和蔼，学生们都愿意向她请教。"}, {"id": 1, "w": "和气", "p": "héqi", "t": "形容词", "m": "điềm đạm, nhã nhặn, hòa thuận", "coll": "和气地说、待人和气", "s": "她待人和气，很快就赢得了邻居们的信任。"}, {"id": 2, "w": "目光", "p": "mùguāng", "t": "名词", "m": "ánh mắt", "coll": "关切的目光、吸引目光", "s": "母亲用关切的目光注视着即将远行的孩子。"}, {"id": 3, "w": "慈祥", "p": "cíxiáng", "t": "形容词", "m": "hiền từ, hiền hậu", "coll": "慈祥的笑容、面容慈祥", "s": "每当我想起奶奶，脑海中就会浮现出她慈祥的笑容。"}, {"id": 4, "w": "跨", "p": "kuà", "t": "动词", "m": "bước", "coll": "跨过门槛、跨出一步", "s": "他鼓起勇气，跨出了独立生活的第一步。"}, {"id": 5, "w": "自主", "p": "zìzhǔ", "t": "形容词", "m": "tự chủ", "coll": "自主选择、自主学习", "s": "父母应该尊重孩子自主选择职业的权利。"}, {"id": 6, "w": "甭", "p": "béng", "t": "副词", "m": "không cần, khỏi phải", "coll": "甭担心、甭客气", "s": "时间还早，你甭着急，先把早饭吃完。"}, {"id": 7, "w": "脱离", "p": "tuōlí", "t": "动词", "m": "thoát khỏi, rời khỏi", "coll": "脱离危险、脱离实际", "s": "经过医生的抢救，受伤的孩子终于脱离了危险。"}, {"id": 8, "w": "诱惑", "p": "yòuhuò", "t": "动词", "m": "mê hoặc, cám dỗ, hấp dẫn", "coll": "抵挡诱惑、充满诱惑", "s": "面对眼前的诱惑，他仍然坚持自己的原则。"}, {"id": 9, "w": "无比", "p": "wúbǐ", "t": "副词／形容词", "m": "không thể sánh được, vô cùng, không gì bằng", "coll": "无比激动、无比珍贵", "s": "得知女儿平安归来，母亲感到无比欣慰。"}, {"id": 10, "w": "向往", "p": "xiàngwǎng", "t": "动词", "m": "mong mỏi, khao khát", "coll": "向往自由、令人向往", "s": "她从小就向往宁静的乡村生活。"}, {"id": 11, "w": "孤独", "p": "gūdú", "t": "形容词", "m": "cô độc, cô đơn", "coll": "感到孤独、孤独的老人", "s": "孩子们离家后，这位老人常常感到孤独。"}, {"id": 12, "w": "哭鼻子", "p": "kū bízi", "t": "动词短语", "m": "khóc (khóc nhè mếu máo)", "coll": "忍不住哭鼻子、别哭鼻子", "s": "小时候，他一受委屈就会哭鼻子。"}, {"id": 13, "w": "片刻", "p": "piànkè", "t": "名词", "m": "phút chốc, giây lát", "coll": "休息片刻、沉默片刻", "s": "他沉默了片刻，才缓缓说出自己的决定。"}, {"id": 14, "w": "步伐", "p": "bùfá", "t": "名词", "m": "bước đi, nhịp bước", "coll": "加快步伐、坚定的步伐", "s": "听见孩子的呼喊，母亲立刻加快了步伐。"}, {"id": 15, "w": "包围", "p": "bāowéi", "t": "动词", "m": "bao quanh, vây quanh", "coll": "被人群包围、包围起来", "s": "记者们很快包围了刚刚走出会场的运动员。"}, {"id": 16, "w": "感染", "p": "gǎnrǎn", "t": "动词", "m": "lây, lan truyền sang", "coll": "受到感染、感染他人", "s": "孩子们的笑声感染了在场的每一个人。"}, {"id": 17, "w": "恨不得", "p": "hènbude", "t": "动词", "m": "nóng lòng muốn, rất mong muốn", "coll": "恨不得马上回家、恨不得立刻出发", "s": "听说父亲生病了，她恨不得马上赶回家。"}, {"id": 18, "w": "眼前", "p": "yǎnqián", "t": "名词", "m": "trước mắt, ngay trước mặt", "coll": "就在眼前、浮现在眼前", "s": "童年的情景又一次浮现在我的眼前。"}, {"id": 19, "w": "团圆", "p": "tuányuán", "t": "动词", "m": "đoàn tụ, sum họp", "coll": "一家团圆、与家人团圆", "s": "无论离家多远，他都盼望春节能与家人团圆。"}, {"id": 20, "w": "近来", "p": "jìnlái", "t": "名词", "m": "dạo này, gần đây", "coll": "近来很忙、近来的变化", "s": "近来，她一直忙着准备毕业论文的答辩。"}, {"id": 21, "w": "酝酿", "p": "yùnniàng", "t": "动词", "m": "ấp ủ, chuẩn bị", "coll": "酝酿计划、酝酿情绪", "s": "这个旅行计划在他心里已经酝酿了很久。"}, {"id": 22, "w": "刹那", "p": "chànà", "t": "名词", "m": "giây lát, chốc lát", "coll": "刹那之间、一刹那", "s": "听到孩子叫妈妈的刹那，她忍不住流下了眼泪。"}, {"id": 23, "w": "反常", "p": "fǎncháng", "t": "形容词", "m": "khác thường, lạ", "coll": "行为反常、反常的表现", "s": "一向活泼的孩子突然变得沉默，这样的表现有些反常。"}, {"id": 24, "w": "埋怨", "p": "mányuàn", "t": "动词", "m": "oán trách", "coll": "互相埋怨、埋怨别人", "s": "遇到困难时，与其互相埋怨，不如一起寻找解决办法。"}, {"id": 25, "w": "体谅", "p": "tǐliàng", "t": "动词", "m": "thông cảm", "coll": "体谅父母、互相体谅", "s": "长大以后，她才逐渐学会体谅父母的不容易。"}, {"id": 26, "w": "无精打采", "p": "wújīng dǎcǎi", "t": "成语", "m": "buồn bã, ủ rũ, phờ phạc, thẫn thờ", "coll": "显得无精打采、无精打采地坐着", "s": "因为整夜没有睡好，他今天看起来无精打采。"}, {"id": 27, "w": "规划", "p": "guīhuà", "t": "动词", "m": "lập kế hoạch", "coll": "规划未来、合理规划", "s": "他认真规划了未来三年的学习和工作。"}, {"id": 28, "w": "熬", "p": "áo", "t": "动词", "m": "chịu đựng", "coll": "熬过难关、熬到天亮", "s": "无论日子多难，一家人总是互相鼓励，一起熬过去。"}, {"id": 29, "w": "漫长", "p": "màncháng", "t": "形容词", "m": "dài dằng dặc", "coll": "漫长的等待、漫长的旅程", "s": "经过漫长的等待，他们终于收到了孩子平安到达的消息。"}, {"id": 30, "w": "寂静", "p": "jìjìng", "t": "形容词", "m": "vắng vẻ, yên tĩnh", "coll": "寂静的夜晚、四周寂静", "s": "寂静的夜晚，窗外偶尔传来几声鸟叫。"}, {"id": 31, "w": "稿件", "p": "gǎojiàn", "t": "名词", "m": "bài viết, bản thảo", "coll": "修改稿件、提交稿件", "s": "编辑仔细修改了这篇稿件中的几处错误。"}, {"id": 32, "w": "难得", "p": "nándé", "t": "形容词", "m": "hiếm có, khó có được", "coll": "机会难得、十分难得", "s": "一家人难得有机会聚在一起，大家都格外珍惜。"}, {"id": 33, "w": "心疼", "p": "xīnténg", "t": "动词", "m": "đau lòng, thương xót", "coll": "心疼孩子、让人心疼", "s": "看到父亲忙了一整天，她十分心疼。"}, {"id": 34, "w": "掩饰", "p": "yǎnshì", "t": "动词", "m": "che đậy, che giấu (khuyết điểm, sai lầm...)", "coll": "掩饰不安、无法掩饰", "s": "他努力用微笑掩饰内心的不安。"}, {"id": 35, "w": "隐瞒", "p": "yǐnmán", "t": "动词", "m": "giấu giếm, giấu kín", "coll": "隐瞒事实、隐瞒病情", "s": "为了不让家人担心，他一直隐瞒着自己的病情。"}, {"id": 36, "w": "唠叨", "p": "láodao", "t": "动词", "m": "lải nhải, nói huyên thuyên", "coll": "不停地唠叨、唠叨几句", "s": "母亲总爱唠叨，提醒我出门前别忘了带伞。"}, {"id": 37, "w": "吃苦", "p": "chī kǔ", "t": "动词", "m": "chịu khổ", "coll": "肯吃苦、吃苦耐劳", "s": "他肯吃苦，也愿意从最基础的工作做起。"}, {"id": 38, "w": "欣慰", "p": "xīnwèi", "t": "形容词", "m": "vui mừng và yên tâm", "coll": "感到欣慰、令人欣慰", "s": "看到孩子懂得照顾别人，父母感到十分欣慰。"}, {"id": 39, "w": "本事", "p": "běnshi", "t": "名词", "m": "bản lĩnh, khả năng", "coll": "有本事、学本事", "s": "与其急着证明自己，不如踏踏实实地学点真本事。"}, {"id": 40, "w": "皱纹", "p": "zhòuwén", "t": "名词", "m": "nếp nhăn", "coll": "脸上的皱纹、长出皱纹", "s": "岁月在母亲的脸上留下了一道道皱纹。"}, {"id": 41, "w": "顿时", "p": "dùnshí", "t": "副词", "m": "ngay tức khắc", "coll": "顿时明白、顿时安静下来", "s": "听到这个好消息，他心中的担忧顿时消失了。"}, {"id": 42, "w": "不由得", "p": "bùyóude", "t": "副词", "m": "không kìm được, không nhịn được", "coll": "不由得笑了、不由得想起", "s": "听着这首熟悉的歌，她不由得想起了远方的家人。"}, {"id": 43, "w": "热泪盈眶", "p": "rèlèi yíngkuàng", "t": "成语", "m": "rơm rớm nước mắt, nước mắt lưng tròng", "coll": "感动得热泪盈眶、激动得热泪盈眶", "s": "多年后再次见到母亲，他激动得热泪盈眶。"}];
